local module = {}

local suffixes = {"K", "M", "B", "T", "Q", "Qu", "S", "Se", "O", "N", "D"}

function module.ToSuffix(n)
	for i = #suffixes, 1, -1 do
		local v = math.pow(10, i * 3)
		if n >= v then
			--return ("%.0f"):format(n / v) .. suffixes[i]
			return ""..(math.floor((n/v)*100)/100)..""..suffixes[i]
		end
	end
	return tostring(n)
end

return module

