local Utility = {}
local Suffixes = {'k','m','b','t','q','s','o','n'}

function Utility.Suffixes(Number: number, Decimals)
	return math.floor(((Number < 1 and Number) or math.floor(Number) / 10 ^ (math.log10(Number) - math.log10(Number) % 3)) * 10 ^ (Decimals or 2)) / 10 ^ (Decimals or 2)..((Suffixes)[math.floor(math.log10(Number) / 3)] or "")
end

function Utility.Round(Val, Decimals)
	Decimals = Decimals or 0
	return math.floor(Val * 10^Decimals) / 10^Decimals
end

function Utility.FormatWithDays(min)
	local Minutes = math.floor(min % 60) 
	local Hours = math.floor(min / 60 % 24)
	local Days = math.floor(min / 1440)
	return Minutes, Hours, Days
end

function Utility.FormatSecondsToMinutes(sec)
	local Minutes = math.floor(sec / 60 % 60) 
	local Hours = math.floor(sec / 3600 % 24)
	return Minutes, Hours
end

function Utility.FormatWithHours(sec)
	return ('%02i:%02i:%02i'):format(sec / 60 ^ 2, sec / 60 % 60, sec % 60)
end 

return Utility

